import{_ as o,o as _,c as t,a2 as e}from"./chunks/framework.BXA5Pi9t.js";const h=JSON.parse('{"title":"2019-Jan-17 :: Ceph Tech Talks - NooBaa: A data platform for distributed hybrid clouds","description":"","frontmatter":{"title":"2019-Jan-17 :: Ceph Tech Talks - NooBaa: A data platform for distributed hybrid clouds","date":"2019-01-19T00:00:00.000Z","updated":"2019-01-19T00:00:00.000Z","tags":["分布式存储","混合云","NooBaa","Ceph","软件定义存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-Jan-17_-_-_Ceph_Tech_Talks_-_NooBaa_-_A_data_platform_for_distributed_hybrid_clouds.md","filePath":"posts/2019/2019-Jan-17_-_-_Ceph_Tech_Talks_-_NooBaa_-_A_data_platform_for_distributed_hybrid_clouds.md","lastUpdated":1780459816000}'),r={name:"posts/2019/2019-Jan-17_-_-_Ceph_Tech_Talks_-_NooBaa_-_A_data_platform_for_distributed_hybrid_clouds.md"};function s(l,a,i,d,p,n){return _(),t("div",null,[...a[0]||(a[0]=[e("<p>NooBaa 是一个针对分布式混合云环境的开源数据平台，该平台旨在帮助企业在多云环境中实现数据管理和优化。在 2019 年 1 月 17 日的 Ceph Tech Talks 中，NooBaa 的研发人员详细介绍了该平台的功能、架构和未来发展方向。</p><p><strong>会议要点</strong>：</p><ul><li><strong>NooBaa 平台介绍</strong>： NooBaa 支持本地、多云环境，通过 API 或本地资源访问。它提供端点抽象，隐藏数据存储位置和性能差异，提供透明访问。平台支持 S3 和 Lambda API，提供丰富的数据管理功能，并确保数据安全。</li><li><strong>数据管理功能</strong>： NooBaa 支持数据放置、数据冗余、对象版本控制、触发器等功能，以提高数据可靠性和效率。</li><li><strong>未来发展方向</strong>： NooBaa 将开源其平台，并计划进行容器化、与 OpenShift 和 Seafarers 集成，并探索联邦应用场景。</li><li><strong>社区参与</strong>： NooBaa 团队鼓励社区成员参与平台的开发和讨论。</li></ul><p><strong>讨论内容</strong>：</p><ul><li>NooBaa 与 Ceph 网关的集成</li><li>数据迁移</li><li>多云管理</li><li>容器化</li><li>Kubernetes 集成</li></ul><p><strong>行动计划</strong>：</p><ul><li>NooBaa 团队将开源平台，并期待社区贡献。</li><li>NooBaa 团队将继续开发容器化、OpenShift 和 Seafarers 集成等功能。</li><li>社区成员将讨论 NooBaa 平台与 Ceph 网关的集成、数据迁移、多云管理等话题。</li></ul>",7)])])}const u=o(r,[["render",s]]);export{h as __pageData,u as default};
